select energy_manager.load_cards($cards$[
{"id":"p3-b05-025","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What did a variable-speed drive on the ID and FD fans of a 25 t/h boiler achieve?","back":"Average power fell by nearly 41 kW, saving about Rs 0.33 million a year. The Rs 0.65 million VSD paid back in under 2 years.","explain":"The boiler's fans were controlled by outlet dampers. A study of the airflow pattern showed a VSD would control flow much more efficiently.","flash":true,"source":"BEE Book 3 Ch 05 p192","order":3286},
{"id":"p3-b05-026","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"What did a backward-curved impeller with erosion liners achieve at a cement plant's clinker cooler fans?","back":"Power consumption fell by 53%, saving about Rs 2.1 million a year. The liners protect the blades from abrasive dust without frequent impeller changes.","explain":"The old straight-blade impeller gave low system efficiency and the flow was higher than required. Replacing the impeller with a backward-curved blade, with liners against erosion, was a simple measure.","flash":false,"source":"BEE Book 3 Ch 05 p192","order":3287},
{"id":"p3-b05-027","paper":3,"topic":"Fans & Blowers","kind":"fact","front":"Why does parallel operation of two fans give less than double the flow in a typical system?","back":"Two identical fans in parallel double the flow only at free delivery. The higher the system resistance, the smaller the flow gain.","explain":"Parallel operation suits low-resistance systems that run close to free delivery. Series (push-pull) operation gives the most benefit in high-resistance systems.","flash":false,"source":"BEE Book 3 Ch 05 p186","order":3288},
{"id":"p3-b05-028","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"Pitot traverse: velocity pressure 47 mm WC, air at 380 °C with density 1.135 kg/m³, pitot coefficient Cp = 0.9. What is the air velocity?","back":"About 25.6 m/s (book value; 25.65 unrounded).","explain":"The pitot velocity equation uses the velocity pressure and gas density at flow conditions. Use the manufacturer's coefficient if known, otherwise 0.85.","flash":false,"source":"BEE Book 3 Ch 05 p189","steps":[{"prompt":"Write the pitot velocity formula.","answer":"V = Cp × √(2 × 9.81 × ΔP ÷ ρ)","explain":"ΔP is the velocity pressure in mm WC and ρ is gas density at flow conditions in kg/m³."},{"prompt":"Insert the values.","answer":"Cp = 0.9, ΔP = 47 mm WC, ρ = 1.135 kg/m³, so V = 0.9 × √(2 × 9.81 × 47 ÷ 1.135)","explain":"Both values are given directly in the question."},{"prompt":"Evaluate inside the square root.","answer":"2 × 9.81 × 47 = 922.1; 922.1 ÷ 1.135 = 812.5","explain":"Compute the numerator first, then divide by density."},{"prompt":"Take the square root and multiply by Cp.","answer":"√812.5 = 28.5; 0.9 × 28.5 = 25.6 m/s","explain":"The book's answer is 25.6 m/s; the unrounded value is 25.65."}],"order":3289},
{"id":"p3-b05-029","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A V-belt fan has a 0.8 m discharge duct, velocity pressure 45 mm WC, Cp 0.9, air at 40 °C, static pressure −20 mm WC at inlet and 185 mm WC at outlet, motor 75 kW, belt 97%, motor 93%. What is the static fan efficiency?","back":"About 37.6% (book value 37.58%).","explain":"Static efficiency uses the flow, the total static rise and the shaft power. Shaft power is motor kW multiplied by belt and motor efficiency.","flash":false,"source":"BEE Book 3 Ch 05 p194","steps":[{"prompt":"Correct the air density to 40 °C.","answer":"ρ = 1.293 × 273 ÷ (273 + 40) = 1.1277 kg/m³","explain":"Standard density at 0 °C is corrected to the actual gas temperature."},{"prompt":"Find the duct area.","answer":"A = 3.14 × 0.8 × 0.8 ÷ 4 = 0.5024 m²","explain":"Area of a circular duct."},{"prompt":"Find the airflow from the pitot reading.","answer":"Q = 0.9 × 0.5024 × √(2 × 9.81 × 45 ÷ 1.1277) = 12.65 m³/s","explain":"Same pitot equation as before, with the corrected density."},{"prompt":"Find the shaft power.","answer":"75 × 0.97 × 0.93 = 67.65 kW","explain":"Belt transmission efficiency and motor efficiency both reduce the motor kW."},{"prompt":"Find the total static pressure rise.","answer":"185 − (−20) = 205 mm WC","explain":"Outlet static minus inlet static."},{"prompt":"Compute the static efficiency.","answer":"η = 12.65 × 205 ÷ (102 × 67.65) = 37.58%","explain":"The 102 is the unit conversion for kW, m³/s and mm WC."}],"order":3290},
{"id":"p3-b05-030","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"Flue gas draft: boiler −10, economiser −30, air heater −40 and dust control −150 mm WC, with the stack needing +10 mm WC at the fan outlet. What pressure rise must the ID fan build?","back":"240 mm WC (outlet +10 minus inlet −230).","explain":"The ID fan must overcome the total draft at its inlet and deliver enough pressure to push gas to the bottom of the stack. The difference between outlet and inlet pressure is the fan's job.","flash":false,"source":"BEE Book 3 Ch 05 p183","steps":[{"prompt":"Sum the inlet draft.","answer":"−10 − 30 − 40 − 150 = −230 mm WC","explain":"Each equipment's draft adds to the total suction at the fan inlet."},{"prompt":"Identify the outlet requirement.","answer":"+10 mm WC at the outlet","explain":"The fan needs about 10 mm WC to push gas to the bottom of the stack, from where natural draft takes over."},{"prompt":"Find the pressure rise the fan must build.","answer":"10 − (−230) = 240 mm WC","explain":"The fan builds the difference between outlet and inlet pressure."}],"order":3291},
{"id":"p3-b05-031","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"Pitot reading in primary air ducting: air at 38 °C, velocity pressure 47 mm WC, Cp = 0.9, standard density 1.293 kg/m³ at 0 °C. What is the air velocity?","back":"About 25.6 m/s.","explain":"The standard density must be corrected to flow temperature before using the pitot formula. The answer matches the book's worked example because the density comes out near 1.135 kg/m³.","flash":false,"source":"BEE Book 3 Ch 05 p197","steps":[{"prompt":"Correct the density to 38 °C.","answer":"ρ = 1.293 × 273 ÷ (273 + 38) = 1.135 kg/m³","explain":"Density falls with temperature, so the corrected value is lower than the 0 °C value."},{"prompt":"Write and insert the pitot formula.","answer":"V = 0.9 × √(2 × 9.81 × 47 ÷ 1.135)","explain":"Cp, velocity pressure and corrected density."},{"prompt":"Evaluate.","answer":"V ≈ 25.6 m/s","explain":"Matches the worked example in the chapter."}],"order":3292},
{"id":"p3-b05-032","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A fan delivers 18,500 Nm³/h at 45 mm WC static pressure. The 3-phase motor draws 2.9 kW per phase on average, with 88% motor efficiency. What is the fan static efficiency?","back":"About 29.6%.","explain":"Static efficiency compares the air power (flow times static pressure) to the shaft power. The motor input is taken per phase and multiplied by three.","flash":false,"source":"BEE Book 3 Ch 05 p197","steps":[{"prompt":"Find the total motor input.","answer":"3 × 2.9 = 8.7 kW","explain":"Three phases, each at 2.9 kW on average."},{"prompt":"Find the shaft power.","answer":"8.7 × 0.88 = 7.66 kW","explain":"Shaft power = motor input × motor efficiency."},{"prompt":"Convert flow to m³/s.","answer":"18,500 ÷ 3600 = 5.14 m³/s","explain":"The chapter's efficiency formula uses m³/s."},{"prompt":"Compute the static efficiency.","answer":"η = 5.14 × 45 ÷ (102 × 7.66) = 29.6%","explain":"The static efficiency formula with 102 as the unit conversion for kW."}],"order":3293},
{"id":"p3-b05-033","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A fan running at 900 rpm delivers 3000 Nm³/h at 600 mm WC static pressure. At 600 rpm, what are the new flow and static pressure?","back":"Flow 2000 Nm³/h. Static pressure about 267 mm WC.","explain":"Flow varies in direct proportion to speed, and pressure varies with the square of speed. Power would vary with the cube of speed.","flash":false,"source":"BEE Book 3 Ch 05 p197","steps":[{"prompt":"Find the speed ratio.","answer":"600 ÷ 900 = 0.667","explain":"New speed over old speed."},{"prompt":"Find the new flow.","answer":"Q2 = 3000 × 0.667 = 2000 Nm³/h","explain":"Flow is proportional to speed."},{"prompt":"Find the new static pressure.","answer":"P2 = 600 × 0.667² = 266.7 mm WC","explain":"Pressure is proportional to speed squared."},{"prompt":"Note the power effect (not asked).","answer":"Power falls to about 0.667³ ≈ 0.30 of the original","explain":"Power is proportional to speed cubed, which is why speed reduction saves the most energy."}],"order":3294},
{"id":"p3-b05-034","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A fan at 970 rpm delivers 3000 Nm³/h at 650 mm WC static pressure. If the speed is reduced to 700 rpm, what static pressure does it develop? Options: a) 388.5 b) 244.3 c) 469 d) none of the above.","back":"About 339 mm WC by the speed-squared law, so the answer is d) none of the above. 244.3 is the cube-law trap.","explain":"The book's OCR of the options is partly garbled, so the answer rests on the chapter's law that pressure varies with speed squared. The option 244.3 comes from using the cube law, which applies to power, not pressure.","flash":false,"source":"BEE Book 3 Ch 05 p196","steps":[{"prompt":"Find the speed ratio.","answer":"700 ÷ 970 = 0.7216","explain":"New speed over old speed."},{"prompt":"Apply the pressure law.","answer":"Pressure ∝ speed²","explain":"The chapter's fan law for static pressure."},{"prompt":"Compute the new pressure.","answer":"650 × 0.7216² = 650 × 0.5208 ≈ 338.5 mm WC","explain":"Square of the speed ratio times the old pressure."},{"prompt":"Compare with the options.","answer":"None matches. 650 × 0.7216³ = 244.2, which is option b, but that uses the cube law.","explain":"Choose d) none of the above."}],"order":3295},
{"id":"p3-b05-035","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A seal air fan at 50 Hz draws 120 kW with its suction damper 25% open. A VFD will replace the damper: the damper opens fully and the motor runs at 33 Hz. Assuming motor and fan efficiency stay constant, what is the power at 33 Hz?","back":"About 34.5 kW.","explain":"Power varies with the cube of speed when efficiencies are constant. Frequency sets speed in proportion for an induction motor.","flash":false,"source":"BEE Book 3 Ch 05 p197","steps":[{"prompt":"Write the fan law for power.","answer":"P2 = P1 × (N2 ÷ N1)³","explain":"Power is proportional to speed cubed."},{"prompt":"Find the frequency ratio.","answer":"33 ÷ 50 = 0.66; 0.66³ = 0.2875","explain":"Speed is proportional to frequency for the same motor."},{"prompt":"Compute the new power.","answer":"120 × 0.2875 = 34.5 kW","explain":"Original power times the cube ratio."}],"order":3296},
{"id":"p3-b05-036","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"An engine room of 30 m × 20 m × 5 m needs 20 air changes per hour. The ventilator fan has a 15 mm WC static rise and 70% fan efficiency. At 90% motor efficiency, what motor power is drawn?","back":"About 3.9 kW (fan shaft about 3.5 kW).","explain":"Airflow comes from room volume times air changes. The static efficiency formula gives fan shaft power, and motor efficiency gives the electrical input.","flash":false,"source":"BEE Book 3 Ch 05 p197","steps":[{"prompt":"Find the room volume.","answer":"30 × 20 × 5 = 3000 m³","explain":"Length × breadth × height."},{"prompt":"Find the airflow.","answer":"3000 × 20 ÷ 3600 = 16.67 m³/s","explain":"Convert air changes per hour to m³/s."},{"prompt":"Find the fan shaft power.","answer":"16.67 × 15 ÷ (102 × 0.70) = 3.50 kW","explain":"Rearranged static efficiency formula: kW = Q × SP ÷ (102 × η)."},{"prompt":"Find the motor input.","answer":"3.50 ÷ 0.90 = 3.89 kW","explain":"Motor input = shaft power ÷ motor efficiency."}],"order":3297},
{"id":"p3-b05-037","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A boiler ID fan is to be sized for 30,000 m³/h at 240 mm WC. Applying the book's ID fan safety margins, what is the design duty?","back":"36,000 m³/h at about 312 mm WC.","explain":"The book gives ID fans a 20% margin on volume and a 30% margin on head. Margins are normally agreed with the process supplier.","flash":false,"source":"BEE Book 3 Ch 05 p182","steps":[{"prompt":"Apply the volume margin.","answer":"30,000 × 1.20 = 36,000 m³/h","explain":"20% on volume for ID fans."},{"prompt":"Apply the head margin.","answer":"240 × 1.30 = 312 mm WC","explain":"30% on head (pressure) for ID fans."},{"prompt":"State the design duty.","answer":"36,000 m³/h at 312 mm WC","explain":"This is the duty to specify when sizing the ID fan."}],"order":3298},
{"id":"p3-b05-038","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"A VSD for boiler fans costs Rs 0.65 million and saves Rs 0.33 million a year. What is the simple payback?","back":"About 2.0 years (1.97). The book says it paid back in under 2 years.","explain":"Simple payback is investment divided by annual saving. It ignores interest and inflation.","flash":false,"source":"BEE Book 3 Ch 05 p192","steps":[{"prompt":"Divide investment by annual saving.","answer":"0.65 ÷ 0.33 = 1.97 years","explain":"Simple payback formula."},{"prompt":"Note the basis of the saving.","answer":"Rs 0.33 million a year comes from the average power cut of about 41 kW.","explain":"The payback depends on the annual saving the study measured."},{"prompt":"Compare with the book.","answer":"Under 2 years, matching the chapter.","explain":"The case study reports a payback under 2 years."}],"order":3299},
{"id":"p3-b05-039","paper":3,"topic":"Fans & Blowers","kind":"problem","front":"After a retrofit, a primary air fan's power falls from 57 kW to 22 kW. What is the percentage reduction?","back":"About 61%.","explain":"Percentage reduction is the drop divided by the original power. The book's case study gives these two values for the belt-driven to direct-coupled retrofit.","flash":false,"source":"BEE Book 3 Ch 05 p192","steps":[{"prompt":"Find the drop in power.","answer":"57 − 22 = 35 kW","explain":"Original minus new power."},{"prompt":"Note the context.","answer":"The retrofit changed a belt-driven arrangement to a direct-coupled fan with a more efficient impeller.","explain":"Both transmission and impeller losses were removed."},{"prompt":"Find the percentage reduction.","answer":"35 ÷ 57 = 0.614 → 61.4%","explain":"Drop divided by original power, times 100."}],"order":3300},
{"id":"p3-b06-001","paper":3,"topic":"Pump Types","kind":"fact","front":"How are pumps classified by operating principle?","back":"As dynamic or displacement pumps. Dynamic pumps are centrifugal or special-effect pumps; displacement pumps are rotary or reciprocating pumps.","explain":"Dynamic pumps add velocity to the liquid and convert it to pressure. Displacement pumps trap a volume and push it through. Centrifugal pumps are the common dynamic type and rotary and reciprocating are the displacement sub-types.","flash":true,"source":"BEE Book 3 Ch 06 p201","order":3301},
{"id":"p3-b06-002","paper":3,"topic":"Centrifugal Pump","kind":"fact","front":"What are the two main parts of a centrifugal pump and what does each do?","back":"The impeller, the only moving part, is attached to a shaft and gives the water velocity. The diffuser (volute) houses the impeller, collects the water and converts velocity to pressure.","explain":"Water enters the eye of the impeller and is thrown outward by centrifugal force, creating low pressure at the eye that draws in more water. The diffuser passages then direct the flow to the discharge, or to the next stage in a multi-stage pump.","flash":false,"source":"BEE Book 3 Ch 06 p201","order":3302},
{"id":"p3-b06-003","paper":3,"topic":"Centrifugal Pump","kind":"fact","front":"What sets the head (pressure) and the capacity of a centrifugal pump?","back":"Head depends on impeller diameter, number of impellers (stages), eye size and shaft speed. Capacity depends on the exit width of the impeller.","explain":"Head and capacity together set the motor horsepower needed. The more water pumped, the more energy required.","flash":false,"source":"BEE Book 3 Ch 06 p201","order":3303},
{"id":"p3-b06-004","paper":3,"topic":"Centrifugal Pump","kind":"fact","front":"True or false: a centrifugal pump is positive acting and always delivers the same volume.","back":"False. It is not positive acting. Flow falls as the depth of water to be lifted increases, and falls further when it pumps against rising pressure.","explain":"Because of this, a centrifugal pump must be selected for the specific job. The head it generates is set by the system it works against.","flash":false,"source":"BEE Book 3 Ch 06 p202","order":3304},
{"id":"p3-b06-005","paper":3,"topic":"Pump Curves","kind":"fact","front":"What are the axes of a standard centrifugal pump performance curve?","back":"Flow is on the horizontal axis. Head, efficiency, power and NPSH required are on the vertical axis, each plotted against flow.","explain":"Head falls gradually as flow rises, and efficiency peaks at one flow. Reading all the curves against the same flow lets you read the duty point, its efficiency and its power together.","flash":false,"source":"BEE Book 3 Ch 06 p202","order":3305},
{"id":"p3-b06-006","paper":3,"topic":"System Characteristics","kind":"fact","front":"What is static head, and is it affected by flow?","back":"Static head is the difference in height between the supply and destination reservoirs. It is independent of flow.","explain":"A system with only static head also includes pumping into a pressurised vessel with short pipe runs. Graphically, static head is a flat line against flow.","flash":true,"source":"BEE Book 3 Ch 06 p203","order":3306},
{"id":"p3-b06-007","paper":3,"topic":"System Characteristics","kind":"fact","front":"How does friction head vary with flow, and how are pipe and fitting losses given?","back":"Friction head is proportional to the square of flow rate. Friction tables give loss per 100 feet (or metres) of pipe at various flows; fittings are given as an equivalent length of the same-size pipe.","explain":"Doubling the flow roughly quadruples the friction loss, which is why friction becomes costly at high flow. Friction is the loss on the liquid in pipes, valves and equipment.","flash":false,"source":"BEE Book 3 Ch 06 p203","order":3307},
{"id":"p3-b06-008","paper":3,"topic":"Pump Operating Point","kind":"fact","front":"Where is a pump's operating point?","back":"Where the pump curve and the system curve intersect.","explain":"Superimposing the two curves gives the actual flow and head. If the real system curve differs from the calculated one, the pump will run at a different flow and head from the expected ones.","flash":false,"source":"BEE Book 3 Ch 06 p205","order":3308},
{"id":"p3-b06-009","paper":3,"topic":"Pumping Example","kind":"problem","front":"A pump moves 68 m³/h against 47 m head with pump A (50% efficient) and pump E (60% efficient). Pump A must be throttled to 76 m head. How much extra motor power does pump A draw, and what is the extra yearly cost at 8000 h/yr and Rs 5.50/kWh?","back":"Pump A draws about 14.9 kW more motor power than pump E (31 kW vs 16.1 kW). That is 1,19,200 kWh/yr, about Rs 6,55,600/yr, more than the price of a new pump.","explain":"Pump A is oversized, so it must be throttled to deliver 68 m³/h. Throttling raises its head to 76 m and its efficiency is only 50%, so motor power rises. The chapter concludes the extra electricity cost exceeds the cost of a new pump.","flash":false,"source":"BEE Book 3 Ch 06 p208","steps":[{"prompt":"Hydraulic power of pump E at 47 m head and 68 m³/h?","answer":"P = (68/3600) × 47 × 1000 × 9.81 / 1000 = 8.7 kW","explain":"Hydraulic power = Q (m³/s) × head (m) × density × g / 1000, with 68 m³/h = 0.01889 m³/s."},{"prompt":"Shaft and motor input power for pump E (pump 60%, motor 90%)?","answer":"Shaft = 8.7 / 0.60 = 14.5 kW; motor input = 14.5 / 0.90 = 16.1 kW","explain":"Shaft power divides by pump efficiency. Motor input divides by motor efficiency."},{"prompt":"Hydraulic power of pump A throttled to 68 m³/h at 76 m head?","answer":"≈ (68/3600) × 76 × 9.81 ≈ 14 kW","explain":"Throttling forces the pump to develop more head for the same flow, so hydraulic power rises with no gain in water delivered."},{"prompt":"Motor input power for pump A at 50% pump and 90% motor efficiency, and the extra over pump E?","answer":"Shaft = 14 / 0.50 = 28 kW; motor = 28 / 0.90 = 31 kW; extra = 31 − 16.1 = 14.9 kW","explain":"The 50% pump efficiency is the main reason the extra power is so large."},{"prompt":"Extra annual energy and cost at 8000 h/yr and Rs 5.50/kWh?","answer":"14.9 × 8000 = 1,19,200 kWh/yr; × Rs 5.50 = Rs 6,55,600/yr","explain":"Compare this running cost with the capital cost of a correctly sized pump. Here the running cost is the bigger figure."}],"order":3309},
{"id":"p3-b06-010","paper":3,"topic":"Affinity Laws","kind":"problem","front":"A pump runs at 3000 rpm giving 100 m³/h, 100 m head and 40 kW. Using the affinity laws, what are the flow, head and power at 1500 rpm?","back":"Flow 50 m³/h, head 25 m, power 5 kW.","explain":"Flow is proportional to speed, head to speed squared, and power to speed cubed. Halving the speed halves the flow, quarters the head and cuts the power to one-eighth.","flash":false,"source":"BEE Book 3 Ch 06 p210","steps":[{"prompt":"New flow when speed halves?","answer":"Q2 = 100 × (1500/3000) = 50 m³/h","explain":"Flow is directly proportional to speed (Q1/Q2 = N1/N2)."},{"prompt":"New head?","answer":"H2 = 100 × (1500/3000)² = 25 m","explain":"Head is proportional to the square of speed."},{"prompt":"New power?","answer":"kW2 = 40 × (1500/3000)³ = 5 kW","explain":"Power is proportional to the cube of speed, so the drop is steep."},{"prompt":"Why is the power saving bigger than the flow saving?","answer":"Flow falls 50%, power falls 87.5%.","explain":"Cubic dependence on speed means small speed cuts give large power savings, which is the basis for energy saving in centrifugal pumps with varying flow."}],"order":3310},
{"id":"p3-b06-011","paper":3,"topic":"Cavitation and NPSH","kind":"fact","front":"What is the difference between NPSHA and NPSHR?","back":"NPSHA (available) is the margin by which pressure at the pump eye exceeds the liquid's vapour pressure. It is a property of the system design. NPSHR (required) is the suction head the pump needs to avoid cavitation. It is a property of the pump design.","explain":"NPSHA falls when suction friction losses rise. NPSHR rises with flow. Cavitation is likely when NPSHA is not safely above NPSHR.","flash":false,"source":"BEE Book 3 Ch 06 p212","order":3311},
{"id":"p3-b06-012","paper":3,"topic":"Cavitation and NPSH","kind":"fact","front":"Name the three undesirable effects of cavitation in a pump.","back":"1) Erosion of impeller vanes, especially with water-based liquids. 2) Increased noise and vibration, with shorter seal and bearing life. 3) Partial choking of impeller passages, reducing performance and, in extreme cases, total loss of developed head.","explain":"Erosion usually starts before any noticeable loss of head, so it is often the first sign of trouble. Cavitation begins where the liquid pressure at the vane inlet drops below vapour pressure.","flash":false,"source":"BEE Book 3 Ch 06 p212","order":3312},
{"id":"p3-b06-013","paper":3,"topic":"Cavitation and NPSH","kind":"fact","front":"How is the onset of cavitation defined by manufacturers and standards?","back":"As the NPSHR at which head drops by 3% compared with cavitation-free head. Prolonged running at that point usually causes damage, so NPSHA should exceed NPSHR by a margin.","explain":"Erosion begins at different NPSHA values than the head drop does. The 3% definition gives a consistent, standard reference point.","flash":false,"source":"BEE Book 3 Ch 06 p213","order":3313},
{"id":"p3-b06-014","paper":3,"topic":"Cavitation and NPSH","kind":"fact","front":"How does NPSHR change with flow and with speed?","back":"NPSHR increases with flow. It varies approximately with the square of speed. At very low speeds NPSHR reaches a minimum plateau and does not fall to zero.","explain":"Higher flow also increases suction friction, lowering NPSHA, so both effects raise cavitation risk. The plateau at low speed means NPSH must be checked carefully in variable-speed pumping.","flash":false,"source":"BEE Book 3 Ch 06 p213","order":3314},
{"id":"p3-b06-015","paper":3,"topic":"Cavitation and NPSH","kind":"problem","front":"A pump has NPSHR of 4 m at 1480 rpm. What is its approximate NPSHR at 1000 rpm?","back":"About 1.83 m, using NPSHR proportional to speed squared.","explain":"The square-law drop is large. The chapter warns that NPSHR does not fall to zero at low speed, so the formula overstates the reduction near the plateau.","flash":false,"source":"BEE Book 3 Ch 06 p213","steps":[{"prompt":"Speed ratio N2/N1?","answer":"1000 / 1480 = 0.676","explain":"Use the ratio of the new speed to the original speed."},{"prompt":"Square the ratio.","answer":"0.676² = 0.457","explain":"NPSHR varies approximately with the square of speed."},{"prompt":"Multiply by the original NPSHR.","answer":"4 m × 0.457 = 1.83 m","explain":"This is the approximate NPSHR at 1000 rpm."},{"prompt":"What is the caveat?","answer":"Near very low speed NPSHR levels off, so the formula is not reliable there.","explain":"Check NPSH against the manufacturer's curve for variable-speed operation."}],"order":3315},
{"id":"p3-b06-016","paper":3,"topic":"Flow Control","kind":"fact","front":"In a friction-only system, what happens to the operating point and power when pump speed is reduced?","back":"The operating point slides along a line of constant efficiency, so the pump stays in its best region and power falls substantially. Variable speed is the ideal control for friction-dominated systems.","explain":"The affinity laws hold in this case, so the reduction in flow and head comes with a large cut in power absorbed.","flash":false,"source":"BEE Book 3 Ch 06 p214","order":3316},
{"id":"p3-b06-017","paper":3,"topic":"Flow Control","kind":"fact","front":"What is the risk of a deep speed reduction in a system with high static head?","back":"Flow and efficiency fall sharply and the pump can run in a damaging region. At the lowest speed in the chapter's example (1184 rpm), the pump cannot lift liquid, flow and efficiency are zero, and the energy input heats the liquid. The pump then becomes a water heater.","explain":"Static head does not fall with speed, so the operating point moves away from the efficient region. The benefit of variable speed is therefore smaller and must be checked case by case.","flash":true,"source":"BEE Book 3 Ch 06 p214","order":3317},
{"id":"p3-b06-018","paper":3,"topic":"Flow Control","kind":"fact","front":"Why does a lower pump speed also extend bearing and seal life?","back":"Hydraulic forces on the impeller fall roughly with the square of speed, so bearing loads drop. Vibration and noise fall and seal life improves, provided the duty point stays in the allowable range.","explain":"The chapter also says bearing life rises as speed falls, but the exponent is unreadable in the OCR, so it is not given here.","flash":false,"source":"BEE Book 3 Ch 06 p215","order":3318},
{"id":"p3-b06-019","paper":3,"topic":"Flow Control","kind":"fact","front":"Is speed regulation or a control valve the more efficient way to control pump flow?","back":"Speed regulation is always more efficient than a control valve.","explain":"A valve wastes energy as a head drop at a given flow. Reducing speed lowers the energy given to the liquid instead, and also lowers bearing load and noise.","flash":true,"source":"BEE Book 3 Ch 06 p215","order":3319},
{"id":"p3-b06-020","paper":3,"topic":"Stop/Start Control","kind":"fact","front":"What does stop/start control need, and what are its caveats?","back":"It needs storage (reservoir, wet well, elevated tank or accumulator) so the pump can run intermittently. Stop/start adds load on transmission parts and heats the motor, so cycle frequency must suit the motor and be checked with the pump maker.","explain":"It saves energy only when intermittent flow is acceptable. Run times can also be shifted into off-peak tariff periods.","flash":false,"source":"BEE Book 3 Ch 06 p216","order":3320},
{"id":"p3-b06-021","paper":3,"topic":"Stop/Start Control","kind":"fact","front":"For minimum energy, should one pump run at full capacity continuously or two pumps alternate under stop/start?","back":"One pump at full capacity running continuously is better than two pumps alternating under stop/start control.","explain":"Pumping at the lowest flow the process allows minimises pipe friction. The chapter's example: pumping at half the flow for twice as long reduces energy to a quarter.","flash":false,"source":"BEE Book 3 Ch 06 p217","order":3321},
{"id":"p3-b06-022","paper":3,"topic":"Flow Control","kind":"fact","front":"Why does a throttle valve waste energy even at maximum flow?","back":"Usual practice is to keep the valve about 10% shut even at maximum flow, so energy is always spent overcoming its resistance. The flow multiplied by the head drop across the valve is wasted energy.","explain":"Pump power falls a little at lower flow, but throttling still wastes energy. Control valve maintenance is also costly on corrosive or solids-laden liquids.","flash":true,"source":"BEE Book 3 Ch 06 p217","order":3322}
]$cards$::jsonb);
